import re
from pathlib import Path
p=Path('/app/gates.txt')
lines=p.read_text().splitlines()
ids=[]
refs=[]
for line in lines:
    m=re.fullmatch(r'out(\d+) = (0|1|out\d+|~out\d+|out\d+ [|&^] out\d+)',line)
    if not m:
        raise SystemExit(f'invalid: {line}')
    ids.append(int(m.group(1)))
    refs += [int(x) for x in re.findall(r'out(\d+)',line.split('=',1)[1])]
if len(lines)>=32000: raise SystemExit('too many lines')
if len(ids)!=len(set(ids)): raise SystemExit('duplicate output')
if max(ids)!=len(set(ids)) and max(ids)<0: raise SystemExit('bad max')
if any(x<0 or x>max(ids) for x in refs): raise SystemExit('bad reference')
if sorted(ids)[-32:] != list(range(max(ids)-31,max(ids)+1)): raise SystemExit('bad final block')
print('line_count',len(lines),'max_signal',max(ids),'valid_gate_syntax',True,'final_block',list(range(max(ids)-31,max(ids)+1)))
